    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT p.service_name parent_svc, c.service_name child_svc, c.span_name, count(*) n, approx_quantile(c.duration,0.5)/1e6 p50_ms, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-ui-dashboard' AND c.service_name='ts-travel-plan-service' GROUP BY 1,2,3 ORDER BY n DESC", "claim": "User-facing dashboard calls to travel-plan travelPlan endpoints take ~130s and fail with HTTP 500."}]}
